import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import QRCode from "qrcode";

// ─── Ikon footer (base64, dari template PPDB) ────────────────────────────
const ICON_PHONE_B64 = "data:image/png;base64,";
const ICON_IG_B64 = "data:image/png;base64,";
const ICON_EMAIL_B64 = "data:image/png;base64,";
const ICON_WEB_B64 = "data:image/png;base64,";
const ICON_LOCATION_B64 = "data:image/png;base64,";

// ─── Helpers (diadaptasi dari template PPDB) ──────────────────────────────
function formatRupiah(angka: number): string {
  return "Rp " + angka.toLocaleString("id-ID");
}

function formatTanggal(date: Date): string {
  return date.toLocaleDateString("id-ID", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

function terbilang(angka: number): string {
  const bilangan = [
    "", "satu", "dua", "tiga", "empat", "lima", "enam",
    "tujuh", "delapan", "sembilan", "sepuluh", "sebelas",
  ];
  if (angka < 12) return bilangan[angka];
  if (angka < 20) return terbilang(angka - 10) + " belas";
  if (angka < 100)
    return terbilang(Math.floor(angka / 10)) + " puluh " + terbilang(angka % 10);
  if (angka < 200) return "seratus " + terbilang(angka - 100);
  if (angka < 1000)
    return terbilang(Math.floor(angka / 100)) + " ratus " + terbilang(angka % 100);
  if (angka < 2000) return "seribu " + terbilang(angka - 1000);
  if (angka < 1000000)
    return terbilang(Math.floor(angka / 1000)) + " ribu " + terbilang(angka % 1000);
  if (angka < 1000000000)
    return (
      terbilang(Math.floor(angka / 1000000)) + " juta " + terbilang(angka % 1000000)
    );
  return "";
}

function loadImg(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

function imgWithOpacity(img: HTMLImageElement, opacity: number): string {
  const canvas = document.createElement("canvas");
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext("2d")!;
  ctx.globalAlpha = opacity;
  ctx.drawImage(img, 0, 0);
  return canvas.toDataURL("image/png");
}

// ─── Tipe data ────────────────────────────────────────────────────────────
export interface BuktiPendaftaranData {
  noPendaftaran: string;
  namaLengkap: string;
  tempatLahir?: string | null;
  tanggalLahir?: string | null;
  gender: "LAKI_LAKI" | "PEREMPUAN" | string;
  noWaSantri: string;
  email: string;
  gelombangNama: string;
  tanggalDaftar: Date;
  biayaPendaftaran: number;
  biayaLayanan: number;
  cekStatusUrl: string;
}

// ─── Generator utama ──────────────────────────────────────────────────────
export const generateBuktiPendaftaranPdf = async (
  data: BuktiPendaftaranData
): Promise<void> => {
  // Muat aset (gagal dimuat = lewati, PDF tetap jadi)
  // Logo Mediator dari public/ ; ikon footer embedded base64.
  // Background ornamen dilewati (aset 820KB tidak ikut push).
  const logoImg = await loadImg("/images/logo-mediator.png").catch(() => null);
  const bgImg = null;
  const iconLocImg = ICON_LOCATION_B64;
  const iconWebImg = ICON_WEB_B64;
  const iconTelImg = ICON_PHONE_B64;
  const iconIgImg = ICON_IG_B64;
  const iconMailImg = ICON_EMAIL_B64;

  const qrDataUrl = await QRCode.toDataURL(data.cekStatusUrl, {
    width: 220,
    margin: 1,
  }).catch(() => null);

  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const pageW = 210;
  const pageH = 297;
  const marginL = 18;
  const marginR = 18;
  const contentW = pageW - marginL - marginR;
  const gold: [number, number, number] = [212, 175, 55];
  const dark: [number, number, number] = [20, 20, 20];
  const brown: [number, number, number] = [60, 40, 10];

  const total = data.biayaPendaftaran + data.biayaLayanan;
  const terbilangText =
    terbilang(total).trim().replace(/\s+/g, " ") + " Rupiah";

  // ── Background ornamen ──
  if (bgImg) {
    doc.addImage(imgWithOpacity(bgImg, 0.15), "PNG", 0, 0, pageW, pageH);
  }

  // ── HEADER: logo Mediator + kop ──
  if (logoImg) {
    doc.addImage(logoImg, "PNG", marginL, 8, 20, 20);
  }
  const textX = marginL + 23;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.setTextColor(...dark);
  doc.text("MEDIATOR", textX, 16);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  doc.setTextColor(...brown);
  doc.text("Markaz Arabiyah", textX, 21);
  doc.setFontSize(8);
  doc.text("Program Pendaftaran Camaba", textX, 26);

  doc.setDrawColor(...gold);
  doc.setLineWidth(0.8);
  doc.line(marginL, 31, pageW - marginR, 31);

  // ── JUDUL ──
  let y = 40;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.setTextColor(...gold);
  doc.text("BUKTI PENDAFTARAN", pageW / 2, y, { align: "center" });
  y += 7;

  // ── NOMOR PENDAFTARAN (menonjol) ──
  doc.setFillColor(253, 250, 240);
  doc.setDrawColor(...gold);
  doc.setLineWidth(0.5);
  doc.rect(marginL, y - 6, contentW, 18, "FD");
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(...brown);
  doc.text("Nomor Pendaftaran", pageW / 2, y, { align: "center" });
  doc.setFontSize(16);
  doc.setTextColor(...dark);
  doc.setFont("courier", "bold");
  doc.text(data.noPendaftaran, pageW / 2, y + 8, { align: "center" });
  doc.setFont("helvetica", "normal");
  y += 20;

  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(...dark);
  doc.text("Tanggal Pendaftaran", marginL, y);
  doc.text(":", marginL + 38, y);
  doc.setFont("helvetica", "normal");
  doc.text(formatTanggal(data.tanggalDaftar), marginL + 41, y);
  y += 8;

  // ── DATA CAMABA ──
  const tglLahir = data.tanggalLahir
    ? new Date(data.tanggalLahir).toLocaleDateString("id-ID", {
        day: "numeric",
        month: "long",
        year: "numeric",
      })
    : "-";
  const rows: [string, string][] = [
    ["Nama Lengkap", data.namaLengkap],
    ["Tempat, Tgl Lahir", `${data.tempatLahir ?? "-"}, ${tglLahir}`],
    ["Jenis Kelamin", data.gender === "LAKI_LAKI" ? "Laki-laki" : "Perempuan"],
    ["No. WhatsApp", data.noWaSantri],
    ["Email", data.email],
    ["Gelombang", data.gelombangNama],
  ];

  doc.setFillColor(253, 250, 240);
  doc.setDrawColor(...gold);
  doc.setLineWidth(0.3);
  doc.rect(marginL - 2, y - 5, contentW + 4, rows.length * 6 + 6, "FD");

  doc.setFontSize(9);
  for (const [label, val] of rows) {
    doc.setFont("helvetica", "bold");
    doc.setTextColor(...brown);
    doc.text(label, marginL, y);
    doc.setTextColor(...dark);
    doc.text(":", marginL + 38, y);
    doc.setFont("helvetica", "normal");
    const wrapped = doc.splitTextToSize(val, contentW - 45);
    doc.text(wrapped, marginL + 41, y);
    y += 5.5 * (wrapped.length > 1 ? wrapped.length * 0.85 : 1);
  }
  y += 4;

  // ── RINCIAN BIAYA ──
  autoTable(doc, {
    startY: y,
    theme: "grid",
    tableWidth: contentW,
    margin: { left: marginL, right: marginR },
    headStyles: {
      fillColor: gold,
      textColor: [255, 255, 255],
      fontStyle: "bold",
      fontSize: 9,
      halign: "center",
    },
    bodyStyles: { fontSize: 9, textColor: dark },
    alternateRowStyles: { fillColor: [252, 248, 238] },
    columnStyles: {
      0: { cellWidth: contentW * 0.65 },
      1: { cellWidth: contentW * 0.35, halign: "right" },
    },
    head: [["Rincian Biaya", "Nominal"]],
    body: [
      ["Biaya Pendaftaran (Tahap 1)", formatRupiah(data.biayaPendaftaran)],
      ["Biaya Layanan Pembayaran", formatRupiah(data.biayaLayanan)],
    ],
    foot: [
      [
        {
          content: "TOTAL",
          styles: {
            fontStyle: "bold",
            halign: "right",
            fillColor: [245, 235, 200] as [number, number, number],
          },
        },
        {
          content: formatRupiah(total),
          styles: {
            fontStyle: "bold",
            halign: "right",
            textColor: gold,
            fillColor: [245, 235, 200] as [number, number, number],
          },
        },
      ],
    ],
    footStyles: { fontSize: 9 },
  });
  y = (doc as any).lastAutoTable.finalY + 4;

  doc.setFont("helvetica", "italic");
  doc.setFontSize(8);
  doc.setTextColor(...brown);
  doc.text(`Terbilang: ${terbilangText}`, marginL, y);
  doc.setTextColor(...dark);
  y += 8;

  // ── TATA CARA PEMBAYARAN ──
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(...dark);
  doc.text("Tata Cara Pembayaran", marginL, y);
  y += 6;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  const steps = [
    "Buka halaman Cek Status (pindai QR di bawah atau buka tautan yang tertera).",
    "Masukkan Nomor Pendaftaran dan Tanggal Lahir camaba.",
    "Klik tombol \"Bayar Sekarang via Midtrans\".",
    "Pilih metode pembayaran: QRIS, Virtual Account bank, atau GoPay.",
    "Selesaikan pembayaran. Status otomatis berubah menjadi LUNAS — tidak perlu konfirmasi manual ke admin.",
  ];
  for (let i = 0; i < steps.length; i++) {
    const lines = doc.splitTextToSize(`${i + 1}. ${steps[i]}`, contentW - 6);
    doc.text(lines, marginL + 3, y);
    y += 5 * lines.length;
  }
  y += 2;

  // ── CATATAN ──
  doc.setDrawColor(...gold);
  doc.setFillColor(253, 250, 240);
  doc.setLineWidth(0.4);
  const note =
    "Simpan Nomor Pendaftaran ini baik-baik. Nomor ini digunakan untuk memantau status pendaftaran dan pembayaran kapan saja melalui halaman Cek Status.";
  const noteLines = doc.splitTextToSize(note, contentW - 6);
  const noteH = noteLines.length * 5 + 6;
  doc.rect(marginL, y, contentW, noteH, "FD");
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(...dark);
  doc.text(noteLines, marginL + 3, y + 4.5);

  // ── FOOTER ──
  const footerTop = pageH - 28;
  doc.setDrawColor(...gold);
  doc.setLineWidth(0.6);
  doc.line(marginL, footerTop, pageW - marginR, footerTop);

  const iconSz = 3.5;
  const fy0 = footerTop + 5;
  const lineGap = 5.5;
  doc.setFontSize(7.5);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(50, 40, 10);

  const contactItems = [
    { icon: iconTelImg, text: "081 212 887788" },
    { icon: iconIgImg, text: "@markazarabiyah" },
    { icon: iconMailImg, text: "markazarabiyah@gmail.com" },
    { icon: iconWebImg, text: "www.markazarabiyah.com" },
  ];
  contactItems.forEach((item, i) => {
    const cy = fy0 + i * lineGap;
    if (item.icon) doc.addImage(item.icon, "PNG", marginL, cy - 2.8, iconSz, iconSz);
    doc.text(item.text, marginL + iconSz + 1.5, cy);
  });

  if (qrDataUrl) {
    const qrSize = 22;
    doc.addImage(qrDataUrl, "PNG", pageW / 2 - 25, footerTop + 3, qrSize, qrSize);
    doc.setFontSize(7);
    doc.text("Pindai untuk Cek Status", pageW / 2 - 25, footerTop + 28);
  }

  const addrX = pageW / 2 + 5;
  const addrLines = [
    "Jalan Cempaka 32, Tegalsari,",
    "Tulungrejo, Pare, Kediri,",
    "Jawa Timur, Indonesia",
  ];
  doc.setFontSize(7.5);
  if (iconLocImg)
    doc.addImage(iconLocImg, "PNG", addrX, fy0 - 0.3, iconSz, iconSz);
  addrLines.forEach((line, i) => {
    doc.text(line, addrX + iconSz + 1.5, fy0 + i * 5.2);
  });

  doc.save(`Bukti-Pendaftaran-${data.noPendaftaran}.pdf`);
};
